def resolve_analysis_depth_settings(
    analysis_depth: str,
    est_method: str,
    custom: dict | None = None,
) -> dict:
    """Resolve performance preset settings used by the sidebar and self-tests."""
    is_mml = est_method == "MML"
    if analysis_depth == "Fast preview":
        settings = {
            "compute_residual_pca": False,
            "compute_strict_marginal": False,
            "strict_marginal_pairwise": False,
            "strict_marginal_max_pair_cells": 400,
            "compute_plausible_values": False,
            "n_plausible_values": 0,
            "plausible_seed": 20260411,
            "bias_mode": "Skip",
            "render_interactive_plots": False,
            "generate_figure_exports": False,
        }
    elif analysis_depth == "Full publication":
        settings = {
            "compute_residual_pca": True,
            "compute_strict_marginal": is_mml,
            "strict_marginal_pairwise": is_mml,
            "strict_marginal_max_pair_cells": 800,
            "compute_plausible_values": is_mml,
            "n_plausible_values": 10 if is_mml else 0,
            "plausible_seed": 20260411,
            "bias_mode": "All facet pairs",
            "render_interactive_plots": True,
            "generate_figure_exports": True,
        }
    elif analysis_depth == "Custom":
        settings = {
            "compute_residual_pca": True,
            "compute_strict_marginal": is_mml,
            "strict_marginal_pairwise": False,
            "strict_marginal_max_pair_cells": 400,
            "compute_plausible_values": is_mml,
            "n_plausible_values": 5 if is_mml else 0,
            "plausible_seed": 20260411,
            "bias_mode": "Selected pair",
            "render_interactive_plots": True,
            "generate_figure_exports": False,
        }
        if custom:
            settings.update(custom)
    else:
        settings = {
            "compute_residual_pca": True,
            "compute_strict_marginal": False,
            "strict_marginal_pairwise": False,
            "strict_marginal_max_pair_cells": 400,
            "compute_plausible_values": False,
            "n_plausible_values": 0,
            "plausible_seed": 20260411,
            "bias_mode": "Selected pair",
            "render_interactive_plots": True,
            "generate_figure_exports": False,
        }

    settings["compute_residual_pca"] = bool(settings.get("compute_residual_pca", True))
    settings["compute_strict_marginal"] = bool(settings.get("compute_strict_marginal", False))
    settings["strict_marginal_pairwise"] = bool(settings.get("strict_marginal_pairwise", False))
    settings["strict_marginal_max_pair_cells"] = int(settings.get("strict_marginal_max_pair_cells", 400))
    settings["compute_plausible_values"] = bool(settings.get("compute_plausible_values", False))
    settings["n_plausible_values"] = int(settings.get("n_plausible_values", 0) or 0)
    settings["plausible_seed"] = int(settings.get("plausible_seed", 20260411) or 20260411)
    settings["bias_mode"] = str(settings.get("bias_mode", "Selected pair"))
    settings["render_interactive_plots"] = bool(settings.get("render_interactive_plots", True))
    settings["generate_figure_exports"] = bool(settings.get("generate_figure_exports", False))

    if not is_mml:
        settings["compute_strict_marginal"] = False
        settings["strict_marginal_pairwise"] = False
        settings["compute_plausible_values"] = False
        settings["n_plausible_values"] = 0
    if not settings["compute_strict_marginal"]:
        settings["strict_marginal_pairwise"] = False
    if not settings["compute_plausible_values"]:
        settings["n_plausible_values"] = 0
    return settings


_RUN_HISTORY_KEY = "_facets_mode_run_history"
_RUN_HISTORY_MAX = 10


def _run_history_extract_summary(output: dict) -> tuple[bool, int, str, str]:
    """Pull Converged / Iterations / Model / Method from the output's summary row."""
    result = output.get("result", {}) if isinstance(output, dict) else {}
    summary = result.get("summary") if isinstance(result, dict) else None
    converged = False
    iters = 0
    model = str(output.get("model_type") or "?") if isinstance(output, dict) else "?"
    method = ""
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        row = summary.iloc[0]
        converged = bool(row.get("Converged", False))
        try:
            iters = int(row.get("Iterations", 0))
        except (TypeError, ValueError):
            iters = 0
        if "Method" in summary.columns:
            method = str(row.get("Method", ""))
        if "Model" in summary.columns and (not model or model == "?"):
            model = str(row.get("Model", model))
    if not method and isinstance(output, dict):
        method = str(output.get("_est_method", ""))
    return converged, iters, model, method


def record_run_in_history(*, output: dict, elapsed_sec: float) -> dict:
    """Push a compact snapshot of this run onto the session history stack.

    Keeps at most _RUN_HISTORY_MAX entries, dropping oldest first. The
    snapshot is a deep copy of `facets_mode_output` so past runs can be
    restored losslessly. Returns the entry just recorded.
    """
    import copy as _copy
    import datetime as _dt

    converged, iters, model, method = _run_history_extract_summary(output)
    facet_cols = output.get("facet_cols", []) if isinstance(output, dict) else []
    n_facets = len(facet_cols) if isinstance(facet_cols, (list, tuple)) else 0
    prep = (output.get("result", {}) or {}).get("prep", {}) if isinstance(output, dict) else {}
    try:
        n_obs = int(prep.get("n_obs", 0))
    except (TypeError, ValueError):
        n_obs = 0
    try:
        n_persons = int(prep.get("n_person", 0))
    except (TypeError, ValueError):
        n_persons = 0

    entry = {
        "run_id": f"run-{_dt.datetime.now().strftime('%Y%m%d-%H%M%S-%f')}",
        "timestamp": _dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "model": model,
        "method": method,
        "n_obs": n_obs,
        "n_persons": n_persons,
        "n_facets": n_facets,
        "converged": converged,
        "iterations": iters,
        "elapsed_sec": float(elapsed_sec or 0.0),
        "output_snapshot": _copy.deepcopy(output) if isinstance(output, dict) else {},
    }
    history = list(st.session_state.get(_RUN_HISTORY_KEY, []))
    history.append(entry)
    if len(history) > _RUN_HISTORY_MAX:
        history = history[-_RUN_HISTORY_MAX:]
    st.session_state[_RUN_HISTORY_KEY] = history
    return entry


def get_run_history() -> list[dict]:
    """Return the current run history list (may be empty)."""
    return list(st.session_state.get(_RUN_HISTORY_KEY, []))


def restore_run_from_history(run_id: str) -> bool:
    """Restore a past run's output snapshot into the live facets_mode_output."""
    import copy as _copy
    for entry in get_run_history():
        if entry.get("run_id") == run_id:
            st.session_state["facets_mode_output"] = _copy.deepcopy(entry["output_snapshot"])
            return True
    return False


def clear_run_history() -> None:
    """Wipe all recorded runs."""
    if _RUN_HISTORY_KEY in st.session_state:
        del st.session_state[_RUN_HISTORY_KEY]


def render_run_history_panel() -> None:
    """Collapsible panel showing recent runs with Restore buttons."""
    history = get_run_history()
    if not history:
        return

    with st.expander(
        f"🕒 Run history ({len(history)} run{'s' if len(history) > 1 else ''})",
        expanded=False,
    ):
        st.caption(
            "Recent analyses in this session. Click **Restore** to swap back to a past "
            "result — the dashboard, tabs, and report will all rebuild from the snapshot."
        )
        # Compact table view (newest first)
        display_rows = []
        for h in reversed(history):
            display_rows.append({
                "timestamp": h["timestamp"],
                "model": h["model"],
                "method": h["method"],
                "n_obs": h["n_obs"],
                "n_persons": h["n_persons"],
                "n_facets": h["n_facets"],
                "converged": h["converged"],
                "iterations": h["iterations"],
                "elapsed_sec": round(h["elapsed_sec"], 2),
            })
        st.dataframe(pd.DataFrame(display_rows), width="stretch", hide_index=True)

        # Per-entry Restore buttons
        for entry in reversed(history):
            cols = st.columns([5, 1])
            label = (
                f"**{entry['timestamp']}** — {entry['model']} / {entry['method']} — "
                f"{'✅ converged' if entry['converged'] else '❌ not converged'}"
                f" — {entry['elapsed_sec']:.1f}s"
            )
            cols[0].markdown(label)
            if cols[1].button(
                "Restore",
                key=f"restore_{entry['run_id']}",
                use_container_width=True,
                help="Load this run's results into the current view.",
            ):
                if restore_run_from_history(entry["run_id"]):
                    st.success(f"Restored run from {entry['timestamp']}")
                    st.rerun()

        st.markdown("---")
        # Two-step confirmation for Clear history — a single stray click
        # used to wipe all snapshots permanently with no recovery path.
        if st.session_state.get("_run_history_clear_confirm", False):
            st.warning(
                f"⚠️ Delete all **{len(history)}** snapshots? "
                "This cannot be undone."
            )
            confirm_cols = st.columns([1, 1, 3])
            if confirm_cols[0].button(
                "Yes, delete all",
                key="run_history_clear_yes",
                type="primary",
                use_container_width=True,
            ):
                clear_run_history()
                st.session_state["_run_history_clear_confirm"] = False
                st.rerun()
            if confirm_cols[1].button(
                "Cancel",
                key="run_history_clear_no",
                use_container_width=True,
            ):
                st.session_state["_run_history_clear_confirm"] = False
                st.rerun()
        else:
            if st.button(
                "🗑 Clear history",
                key="run_history_clear",
                help="Remove all stored snapshots. Requires confirmation.",
            ):
                st.session_state["_run_history_clear_confirm"] = True
                st.rerun()


def _comparison_extract_label(snapshot: dict) -> str:
    """Build a short 'MODEL / METHOD' label from a run snapshot."""
    model = str(snapshot.get("model_type", "") or "")
    method = str(snapshot.get("_est_method", "") or "")
    summary = (snapshot.get("result") or {}).get("summary")
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        row = summary.iloc[0]
        if "Model" in summary.columns and not model:
            model = str(row.get("Model", model))
        if "Method" in summary.columns and not method:
            method = str(row.get("Method", method))
    return f"{model or '?'} / {method or '?'}"


def _comparison_extract_conv(snapshot: dict) -> tuple[bool, int]:
    summary = (snapshot.get("result") or {}).get("summary")
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        row = summary.iloc[0]
        try:
            iters = int(row.get("Iterations", 0))
        except (TypeError, ValueError):
            iters = 0
        return bool(row.get("Converged", False)), iters
    return False, 0


def _comparison_measures_diff(snap_a: dict, snap_b: dict) -> dict | None:
    """Merge the two runs' measures on (Facet, Level) and compute corr + RMSE."""
    da = (snap_a.get("diagnostics") or {}).get("measures")
    db = (snap_b.get("diagnostics") or {}).get("measures")
    if not isinstance(da, pd.DataFrame) or not isinstance(db, pd.DataFrame):
        return None
    if da.empty or db.empty:
        return None
    req = {"Facet", "Level", "Estimate"}
    if not req.issubset(da.columns) or not req.issubset(db.columns):
        return None
    left = da[["Facet", "Level", "Estimate"]].rename(columns={"Estimate": "Estimate_A"})
    right = db[["Facet", "Level", "Estimate"]].rename(columns={"Estimate": "Estimate_B"})
    merged = left.merge(right, on=["Facet", "Level"], how="inner")
    if merged.empty:
        return {"merged": merged, "correlation": float("nan"), "rmse": float("nan"), "n_overlap": 0}
    ea = pd.to_numeric(merged["Estimate_A"], errors="coerce")
    eb = pd.to_numeric(merged["Estimate_B"], errors="coerce")
    valid = ea.notna() & eb.notna()
    n_valid = int(valid.sum())
    corr = float(np.corrcoef(ea[valid], eb[valid])[0, 1]) if n_valid >= 2 else float("nan")
    rmse = float(np.sqrt(np.mean((ea[valid] - eb[valid]) ** 2))) if n_valid else float("nan")
    merged["diff"] = eb - ea
    return {"merged": merged, "correlation": corr, "rmse": rmse, "n_overlap": n_valid}


def _comparison_reliability_diff(snap_a: dict, snap_b: dict) -> pd.DataFrame | None:
    ra = (snap_a.get("diagnostics") or {}).get("reliability")
    rb = (snap_b.get("diagnostics") or {}).get("reliability")
    if not isinstance(ra, pd.DataFrame) or not isinstance(rb, pd.DataFrame):
        return None
    if ra.empty or rb.empty or "Facet" not in ra.columns or "Facet" not in rb.columns:
        return None
    keep = ["Facet", "Separation", "Reliability", "Strata"]
    la = ra[[c for c in keep if c in ra.columns]].rename(columns={
        "Separation": "Separation_A", "Reliability": "Reliability_A", "Strata": "Strata_A",
    })
    lb = rb[[c for c in keep if c in rb.columns]].rename(columns={
        "Separation": "Separation_B", "Reliability": "Reliability_B", "Strata": "Strata_B",
    })
    return la.merge(lb, on="Facet", how="outer")


def render_comparison_panel(snap_a: dict, snap_b: dict) -> None:
    """Render a side-by-side comparison between two run snapshots."""
    label_a = _comparison_extract_label(snap_a)
    label_b = _comparison_extract_label(snap_b)
    conv_a, iters_a = _comparison_extract_conv(snap_a)
    conv_b, iters_b = _comparison_extract_conv(snap_b)

    with st.container(border=True):
        st.markdown(f"### 🔀 Comparison: `{label_a}` vs `{label_b}`")

        cols = st.columns(2)
        cols[0].metric(
            "Convergence",
            "✅ both" if conv_a and conv_b else
            ("⚠️ A only" if conv_a else ("⚠️ B only" if conv_b else "❌ neither")),
        )
        cols[1].metric(
            "Iterations",
            f"{iters_a} vs {iters_b}",
            delta=iters_b - iters_a,
            delta_color="inverse",
        )

        measures = _comparison_measures_diff(snap_a, snap_b)
        if measures is not None:
            st.markdown("#### Element-level measure agreement")
            if measures["n_overlap"] == 0:
                st.info(
                    "No overlapping (Facet, Level) elements between the two runs — "
                    "measures cannot be compared."
                )
            else:
                mcols = st.columns(3)
                mcols[0].metric("Overlap (elements)", measures["n_overlap"])
                mcols[1].metric(
                    "Pearson r",
                    f"{measures['correlation']:.4f}" if pd.notna(measures["correlation"]) else "n/a",
                )
                mcols[2].metric(
                    "RMSE",
                    f"{measures['rmse']:.3f}" if pd.notna(measures["rmse"]) else "n/a",
                )
                # Scatter (45° reference)
                try:
                    fig = go.Figure()
                    for facet, grp in measures["merged"].groupby("Facet"):
                        fig.add_trace(go.Scatter(
                            x=grp["Estimate_A"], y=grp["Estimate_B"],
                            mode="markers", name=str(facet),
                            text=grp["Level"], hovertemplate="<b>%{text}</b><br>A=%{x:.3f}<br>B=%{y:.3f}<extra></extra>",
                        ))
                    est_min = float(min(measures["merged"]["Estimate_A"].min(),
                                        measures["merged"]["Estimate_B"].min()))
                    est_max = float(max(measures["merged"]["Estimate_A"].max(),
                                        measures["merged"]["Estimate_B"].max()))
                    fig.add_shape(type="line", x0=est_min, y0=est_min, x1=est_max, y1=est_max,
                                  line=dict(color="gray", dash="dash", width=1))
                    fig.update_layout(
                        xaxis_title=f"Estimate — {label_a}",
                        yaxis_title=f"Estimate — {label_b}",
                        title="Element measures (dashed line = perfect agreement)",
                        height=420, template="plotly_white",
                    )
                    st.plotly_chart(fig, width="stretch")
                except Exception:
                    st.dataframe(measures["merged"].head(20), width="stretch", hide_index=True)

                with st.expander("Top 10 elements by |diff|", expanded=False):
                    sorted_diff = measures["merged"].reindex(
                        measures["merged"]["diff"].abs().sort_values(ascending=False).index
                    ).head(10)
                    st.dataframe(sorted_diff, width="stretch", hide_index=True)

                # Interpretation
                corr = measures["correlation"]
                if pd.notna(corr):
                    if corr >= 0.98:
                        st.success(f"Near-perfect agreement (r = {corr:.3f}). Methods produce effectively identical measures.")
                    elif corr >= 0.90:
                        st.info(f"Strong agreement (r = {corr:.3f}). Differences are minor; either method is defensible.")
                    elif corr >= 0.70:
                        st.warning(f"Moderate agreement (r = {corr:.3f}). Inspect the scatter for outlier elements.")
                    else:
                        st.error(f"Weak agreement (r = {corr:.3f}). Methods disagree substantially; check assumptions.")

        reliability = _comparison_reliability_diff(snap_a, snap_b)
        if reliability is not None:
            st.markdown("#### Reliability / separation")
            st.dataframe(reliability.round(3), width="stretch", hide_index=True)


def render_comparison_selector() -> None:
    """Expander that lets the user pick two runs from history and compare."""
    history = get_run_history()
    if len(history) < 2:
        return
    with st.expander("🔀 Compare two runs", expanded=False):
        st.caption(
            "Pick two analyses from your run history to view a side-by-side "
            "comparison of convergence, element measures, and reliability."
        )
        labels = [
            f"{h['timestamp']} — {h['model']}/{h['method']}"
            + (" — ✅" if h["converged"] else " — ❌")
            + f" ({h['iterations']} iter, {h['elapsed_sec']:.1f}s)"
            for h in history
        ]
        cols = st.columns([5, 5, 2])
        idx_a = cols[0].selectbox(
            "Run A",
            options=list(range(len(labels))),
            format_func=lambda i: labels[i],
            index=max(0, len(labels) - 2),
            key="compare_run_a",
        )
        idx_b = cols[1].selectbox(
            "Run B",
            options=list(range(len(labels))),
            format_func=lambda i: labels[i],
            index=len(labels) - 1,
            key="compare_run_b",
        )
        do_compare = cols[2].button(
            "Compare",
            key="compare_trigger",
            use_container_width=True,
            type="primary",
        )
        if do_compare:
            if idx_a == idx_b:
                st.info("Pick two different runs to compare.")
                return
            render_comparison_panel(
                history[idx_a]["output_snapshot"],
                history[idx_b]["output_snapshot"],
            )


_READINESS_ICON: dict[str, str] = {"ok": "🟢", "warning": "🟡", "issue": "🔴"}


def _readiness_severity_max(*severities: str) -> str:
    """Combine severities: issue > warning > ok."""
    order = {"ok": 0, "warning": 1, "issue": 2}
    reverse = {v: k for k, v in order.items()}
    return reverse[max(order.get(s, 0) for s in severities)]


def build_readiness_report(
    *,
    data: pd.DataFrame,
    person_col: str,
    score_col: str,
    facet_cols: list[str],
) -> dict:
    """Build a pre-estimation readiness report from the uploaded data.

    Returns a dict with:
        overall     -- "ok" | "warning" | "issue"
        checks      -- list of {"name", "severity", "headline", "detail"}
        n_issues, n_warnings

    Each check diagnoses one dimension (n_obs, n_persons, score column,
    facet cardinality, facet coverage, column role overlap). The UI
    renders this as a traffic-light banner with an expandable detail panel.
    """
    if data is None or (hasattr(data, "empty") and data.empty):
        return {
            "overall": "issue",
            "checks": [{
                "name": "data", "severity": "issue",
                "headline": "No data uploaded",
                "detail": "Upload a CSV/TSV file or load sample data to run MFRM.",
            }],
            "n_issues": 1, "n_warnings": 0,
        }

    facet_cols = list(facet_cols)
    checks: list[dict] = []

    # Column role overlap check
    seen: dict[str, list[str]] = {}
    for role, col in [("Person", person_col), ("Score", score_col)] + [
        (f"Facet[{i}]", f) for i, f in enumerate(facet_cols)
    ]:
        seen.setdefault(col, []).append(role)
    conflicts = {col: roles for col, roles in seen.items() if len(roles) > 1}
    if conflicts:
        first_col, first_roles = next(iter(conflicts.items()))
        checks.append({
            "name": "column_overlap", "severity": "issue",
            "headline": f"Column `{first_col}` assigned to multiple roles",
            "detail": f"Roles: {', '.join(first_roles)}. Each column must serve exactly one role.",
        })

    # N observations
    n = len(data)
    if n >= 300:
        checks.append({
            "name": "n_observations", "severity": "ok",
            "headline": f"{n:,} observations",
            "detail": "Good sample size for reliable MFRM estimation.",
        })
    elif n >= 100:
        checks.append({
            "name": "n_observations", "severity": "warning",
            "headline": f"{n:,} observations (low)",
            "detail": "MFRM needs ≥100 observations for usable estimates; ≥300 recommended.",
        })
    else:
        checks.append({
            "name": "n_observations", "severity": "issue",
            "headline": f"{n:,} observations (too few)",
            "detail": "Need at least ~30 observations to estimate measures; 100+ preferred.",
        })

    # N persons
    if person_col not in data.columns:
        checks.append({
            "name": "n_persons", "severity": "issue",
            "headline": "Person column missing",
            "detail": f"Column `{person_col}` not found in the data.",
        })
    else:
        np_count = data[person_col].nunique()
        if np_count >= 30:
            checks.append({
                "name": "n_persons", "severity": "ok",
                "headline": f"{np_count} unique persons",
                "detail": "Sufficient person sample for ability estimation.",
            })
        elif np_count >= 10:
            checks.append({
                "name": "n_persons", "severity": "warning",
                "headline": f"{np_count} unique persons (low)",
                "detail": "Person reliability will be weak with <30 persons.",
            })
        else:
            checks.append({
                "name": "n_persons", "severity": "issue",
                "headline": f"{np_count} unique persons (too few)",
                "detail": "Need ≥10 persons; person measures are unstable with fewer.",
            })

    # Score column
    if score_col not in data.columns:
        checks.append({
            "name": "score", "severity": "issue",
            "headline": "Score column missing",
            "detail": f"Column `{score_col}` not found in the data.",
        })
    else:
        scores = pd.to_numeric(data[score_col], errors="coerce")
        n_numeric = int(scores.notna().sum())
        n_total = len(scores)
        if n_numeric == 0:
            checks.append({
                "name": "score", "severity": "issue",
                "headline": "Score column has no numeric values",
                "detail": "All values in the Score column are non-numeric. Check for text labels.",
            })
        else:
            missing_pct = (1 - n_numeric / max(n_total, 1)) * 100
            unique = scores.dropna().unique()
            n_unique = len(unique)
            if missing_pct > 50:
                checks.append({
                    "name": "score", "severity": "issue",
                    "headline": f"Score column is {missing_pct:.0f}% missing",
                    "detail": "Over half of score values are missing or non-numeric.",
                })
            elif n_unique < 2:
                checks.append({
                    "name": "score", "severity": "issue",
                    "headline": f"Score has only {n_unique} unique value",
                    "detail": "MFRM needs at least 2 rating categories.",
                })
            elif n_unique > 15:
                checks.append({
                    "name": "score", "severity": "warning",
                    "headline": f"Score has {n_unique} unique values",
                    "detail": "Typical rating scales have 2–7. Consider whether this is continuous.",
                })
            elif missing_pct > 20:
                checks.append({
                    "name": "score", "severity": "warning",
                    "headline": f"Score is {missing_pct:.0f}% missing",
                    "detail": f"Missing rate is {missing_pct:.0f}% — expect reduced effective sample size.",
                })
            else:
                checks.append({
                    "name": "score", "severity": "ok",
                    "headline": f"Score: {n_unique} categories, {missing_pct:.0f}% missing",
                    "detail": f"Looks well-formed.",
                })

    # Facet count
    if len(facet_cols) < 2:
        checks.append({
            "name": "n_facets", "severity": "issue",
            "headline": f"{len(facet_cols)} facet(s) selected",
            "detail": "MFRM needs at least 2 facets (e.g., Rater + Task).",
        })
    else:
        checks.append({
            "name": "n_facets", "severity": "ok",
            "headline": f"{len(facet_cols)} facets selected",
            "detail": f"Facets: {', '.join(facet_cols)}",
        })

    # Per-facet level count
    for facet in facet_cols:
        if facet not in data.columns:
            checks.append({
                "name": f"facet:{facet}", "severity": "issue",
                "headline": f"`{facet}` column missing",
                "detail": f"Column `{facet}` not found in the data.",
            })
            continue
        levels = data[facet].nunique()
        if levels < 2:
            checks.append({
                "name": f"facet:{facet}", "severity": "issue",
                "headline": f"`{facet}` has only {levels} level",
                "detail": "Every facet needs ≥2 levels to estimate a severity/difficulty measure.",
            })
        elif levels > 100:
            checks.append({
                "name": f"facet:{facet}", "severity": "warning",
                "headline": f"`{facet}` has {levels} levels",
                "detail": (
                    f"High-cardinality facets ({levels}+ levels) slow estimation and "
                    "produce noisy measures. Consider grouping levels."
                ),
            })
        else:
            checks.append({
                "name": f"facet:{facet}", "severity": "ok",
                "headline": f"`{facet}`: {levels} levels",
                "detail": f"OK",
            })

    # Per-person coverage (each person should see ≥2 distinct facet-level combos)
    try:
        if person_col in data.columns and facet_cols and all(f in data.columns for f in facet_cols):
            grouped = data.groupby(person_col)[facet_cols].nunique()
            per_person_combos = grouped.prod(axis=1) if len(facet_cols) > 1 else grouped.iloc[:, 0]
            single_obs_persons = int((per_person_combos <= 1).sum())
            total_persons = int(len(grouped))
            if single_obs_persons == 0:
                checks.append({
                    "name": "coverage", "severity": "ok",
                    "headline": "Every person has ≥2 observations",
                    "detail": "Good coverage across facet levels.",
                })
            else:
                frac = single_obs_persons / max(total_persons, 1)
                if frac > 0.5:
                    checks.append({
                        "name": "coverage", "severity": "issue",
                        "headline": f"{single_obs_persons}/{total_persons} persons have only 1 observation",
                        "detail": (
                            f"{frac:.0%} of persons never see multiple facet-level combinations; "
                            "person measures cannot be estimated precisely."
                        ),
                    })
                else:
                    checks.append({
                        "name": "coverage", "severity": "warning",
                        "headline": f"{single_obs_persons}/{total_persons} persons have only 1 observation",
                        "detail": f"{frac:.0%} of persons have limited coverage — their measures will be imprecise.",
                    })
    except Exception:  # pragma: no cover - defensive
        pass

    overall = "ok"
    for c in checks:
        overall = _readiness_severity_max(overall, c["severity"])

    return {
        "overall": overall,
        "checks": checks,
        "n_issues": sum(1 for c in checks if c["severity"] == "issue"),
        "n_warnings": sum(1 for c in checks if c["severity"] == "warning"),
    }


def render_readiness_panel(report: dict) -> None:
    """Streamlit panel showing the readiness traffic-light + details."""
    overall = report.get("overall", "ok")
    checks = report.get("checks", [])
    icon = _READINESS_ICON.get(overall, "⚪")

    if overall == "ok":
        st.success(f"{icon} **Ready to run.** All {len(checks)} data-quality checks passed.")
        with st.expander("Show data quality detail", expanded=False):
            _render_readiness_checklist(checks)
        return

    if overall == "warning":
        n_w = report.get("n_warnings", 0)
        st.warning(
            f"{icon} **Proceed with caution.** {n_w} warning(s) found — "
            "you can still run, but results may be weak. See details below."
        )
        with st.expander("Show all checks", expanded=True):
            _render_readiness_checklist(checks)
        return

    # issue
    st.error(
        f"{icon} **Not ready to run.** {report.get('n_issues', 0)} issue(s) will block "
        "or degrade estimation. Fix the red items below before clicking Run."
    )
    with st.expander("Show all checks", expanded=True):
        _render_readiness_checklist(checks)


def _render_readiness_checklist(checks: list[dict]) -> None:
    for c in checks:
        icon = _READINESS_ICON.get(c.get("severity", "ok"), "⚪")
        st.markdown(f"{icon} **{c['headline']}** — {c['detail']}")


