def _category_curve_export_frame(curve: dict, label: str | None = None) -> pd.DataFrame:
    if not isinstance(curve, dict) or not curve.get("available"):
        return pd.DataFrame()
    prob = curve.get("probability", pd.DataFrame())
    expected = curve.get("expected", pd.DataFrame())
    if not isinstance(prob, pd.DataFrame) or prob.empty:
        return pd.DataFrame()
    out = prob.merge(expected, on="Theta", how="left") if isinstance(expected, pd.DataFrame) else prob.copy()
    meta = curve.get("metadata", {})
    if isinstance(meta, dict):
        for key, value in meta.items():
            out[key] = value
    if label is not None:
        out["CurveLabel"] = str(label)
    return out


def category_probability_curve_export_table(result: dict) -> pd.DataFrame:
    """Long-form category curve data for all available curve scopes."""
    options = category_probability_curve_options(result)
    frames = []
    for row in options.itertuples(index=False):
        try:
            is_average = bool(getattr(row, "IsAverage"))
            level_idx = None if is_average else int(getattr(row, "LevelIndex"))
            curve = build_category_probability_curve_data(result, step_level_index=level_idx)
            frame = _category_curve_export_frame(curve, label=getattr(row, "Label"))
            if not frame.empty:
                frames.append(frame)
        except Exception:
            continue
    return pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()


def _make_category_probability_curve_figures(curve: dict) -> tuple[go.Figure | None, go.Figure | None]:
    if not isinstance(curve, dict) or not curve.get("available"):
        return None, None
    prob_long = curve.get("probability", pd.DataFrame())
    expected_df = curve.get("expected", pd.DataFrame())
    thresholds = curve.get("thresholds", pd.DataFrame())
    meta = curve.get("metadata", {})
    if not isinstance(prob_long, pd.DataFrame) or prob_long.empty or not isinstance(meta, dict):
        return None, None

    rating_min = int(prob_long["CategoryValue"].min()) if "CategoryValue" in prob_long.columns else 0
    rating_max = int(prob_long["CategoryValue"].max()) if "CategoryValue" in prob_long.columns else rating_min
    theta_lo = float(meta.get("ThetaMin", -4.0))
    theta_hi = float(meta.get("ThetaMax", 4.0))
    model = str(meta.get("Model", "Model"))
    scope = str(meta.get("Scope", "curve"))

    colors = px.colors.qualitative.Set2
    fig = go.Figure()
    for idx, (category, group) in enumerate(prob_long.groupby("Category", sort=False)):
        fig.add_trace(go.Scatter(
            x=group["Theta"], y=group["Probability"], mode="lines",
            name=str(category),
            line=dict(color=colors[idx % len(colors)], width=2),
        ))
    for tau in pd.to_numeric(thresholds.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna():
        fig.add_vline(x=float(tau), line_dash="dot", line_color="gray", line_width=0.6)
    fig.update_layout(
        xaxis_title="Person Measure - Item Measure (logits)",
        yaxis_title="Probability",
        title=f"Category Probability Curves ({model}: {scope})",
        yaxis=dict(range=[0, 1]), xaxis=dict(range=[theta_lo, theta_hi]),
        hovermode="x unified", height=450, template="plotly_white",
    )

    fig_expected = None
    if isinstance(expected_df, pd.DataFrame) and not expected_df.empty:
        fig_expected = go.Figure()
        fig_expected.add_trace(go.Scatter(
            x=expected_df["Theta"], y=expected_df["ExpectedScore"], mode="lines",
            line=dict(color="#1b9e77", width=2), name="Expected Score",
        ))
        for tau in pd.to_numeric(thresholds.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna():
            fig_expected.add_vline(x=float(tau), line_dash="dot", line_color="gray", line_width=0.6)
        fig_expected.update_layout(
            xaxis_title="Person Measure - Item Measure (logits)",
            yaxis_title="Expected Score",
            title=f"Expected Score (Model ICC: {scope})",
            yaxis=dict(range=[rating_min, rating_max]),
            hovermode="x unified", height=350, template="plotly_white",
        )
    return fig, fig_expected


def _draw_category_probability_curves_plotly(result: dict) -> None:
    """Interactive Plotly category probability curves."""
    st.subheader("Category Probability Curves")
    st.caption(
        "These curves show the probability of responding in each category as a "
        "function of the latent measure (theta). Hover to read exact P(k) at any theta. "
        "For PCM/GPCM, inspect both the averaged curve and each step-facet level."
    )

    config = result.get("config", {})
    model = config.get("model", "RSM")
    options = category_probability_curve_options(result)
    selected_level_index: int | None = None
    if model in {"PCM", "GPCM"} and not options.empty and len(options) > 1:
        selected_option = st.selectbox(
            "Curve scope",
            options["OptionIndex"].astype(int).tolist(),
            format_func=lambda idx: str(options.loc[options["OptionIndex"] == idx, "Label"].iloc[0]),
            key=f"category_curve_scope_{model}_{config.get('step_facet')}",
            help=(
                "Average gives a compact overview. Level-specific curves use the thresholds "
                "and, for GPCM, the slope for the selected step-facet level."
            ),
        )
        selected_row = options.loc[options["OptionIndex"] == selected_option].iloc[0]
        if not bool(selected_row["IsAverage"]):
            selected_level_index = int(selected_row["LevelIndex"])
    curve = build_category_probability_curve_data(result, step_level_index=selected_level_index)
    if not curve.get("available"):
        st.info(curve.get("reason", "Step parameters not available."))
        return

    meta = curve["metadata"]

    if model in {"PCM", "GPCM"}:
        slope_note = f" Slope used for this curve: {float(meta['Slope']):.3f}." if model == "GPCM" else ""
        st.info(
            f"Curve scope: **{meta['Scope']}**.{slope_note} "
            "Use level-specific curves when category functioning may differ across tasks, raters, or criteria."
        )

    with st.expander("How to read category curves", expanded=False):
        st.markdown(
            """
- Each colored line is the model-predicted probability of a rating category.
- A well-functioning category usually has a visible peak where it is more probable than neighboring categories.
- If a category never becomes most probable, inspect sparse counts and threshold ordering before reporting the scale as fully ordered.
- For PCM/GPCM, the averaged curve can hide level-specific disorder. Use the scope selector to inspect each step-facet level.
- For GPCM, the slope changes steepness, not severity. Read slope differences separately from ordinary Rasch measures.
"""
        )

    fig, fig_expected = _make_category_probability_curve_figures(curve)
    scope_key = re.sub(r"[^A-Za-z0-9]+", "_", str(meta.get("Scope", "curve"))).strip("_")[:80] or "curve"
    if fig is not None:
        st.plotly_chart(fig, width="stretch")
        render_chart_guide("category_probability")
        _offer_fig_download(fig, f"category_probability_curve_{model}_{scope_key}", "Download displayed category curve (PNG 300 DPI)")
    if fig_expected is not None:
        st.plotly_chart(fig_expected, width="stretch")
        _offer_fig_download(fig_expected, f"expected_score_curve_{model}_{scope_key}", "Download displayed expected score curve (PNG 300 DPI)")

    curve_export = _category_curve_export_frame(curve)
    st.download_button(
        "Download displayed category curve data (CSV)",
        data=to_csv_bytes(curve_export),
        file_name="mfrm_category_probability_curve.csv",
        mime="text/csv",
        key=f"dl_category_probability_curve_{model}_{meta['Scope']}",
    )


def _draw_pathway_map_plotly(diagnostics: dict) -> None:
    """Interactive Plotly pathway map: Measure vs Infit ZSTD."""
    st.subheader("Pathway Map")
    st.caption(
        "Each point represents a facet element. Hover to identify elements. "
        "Elements beyond ±2 ZSTD warrant investigation."
    )

    with st.expander("How to read the Pathway Map", expanded=False):
        st.markdown(
            """
The Pathway Map plots each facet element's **measure** (Y-axis, in logits) against its
**Infit ZSTD** (X-axis).

**Reading the plot:**
- **Y-axis (Measure)**: The estimated severity/difficulty of each element.
  Higher values = more severe raters or harder items.
- **X-axis (Infit ZSTD)**: How much the element's response pattern deviates from model
  expectations. A z-score where 0 means perfect fit.
- **Green zone (|ZSTD| < 2)**: Elements in this zone fit the model well. Their response
  patterns are consistent with the Rasch model expectations.
- **Red dashed lines (±2 ZSTD)**: Elements beyond these lines show statistically
  significant misfit. Investigate their response patterns.

**What to look for:**
- *Elements far to the right (ZSTD > +2)*: Noisy — responses are more variable than expected.
  The rater may be inconsistent, or the item may be ambiguous.
- *Elements far to the left (ZSTD < −2)*: Over-fit — responses are too predictable.
  Possible response dependencies or restricted range.
- *Clusters of misfitting elements at similar measures*: May indicate a systematic issue
  at that difficulty level (e.g., a problematic rubric criterion).
- *Isolated outliers*: Often driven by a few unexpected responses (check Outfit too).
"""
        )

    measures = diagnostics.get("measures", pd.DataFrame())
    if measures.empty or "Estimate" not in measures.columns:
        st.info("Measures not available for pathway map.")
        return

    zstd_col = "InfitZSTD" if "InfitZSTD" in measures.columns else None
    if zstd_col is None:
        st.info("Infit ZSTD not available.")
        return

    pdf = measures.copy()
    pdf["Estimate"] = pd.to_numeric(pdf["Estimate"], errors="coerce")
    pdf[zstd_col] = pd.to_numeric(pdf[zstd_col], errors="coerce")
    pdf = pdf.dropna(subset=["Estimate", zstd_col])

    color_col = "Facet" if "Facet" in pdf.columns else None
    hover_data = ["Level"] if "Level" in pdf.columns else None

    fig = px.scatter(
        pdf, x=zstd_col, y="Estimate", color=color_col,
        hover_data=hover_data, opacity=0.7,
        color_discrete_sequence=px.colors.qualitative.Set2,
    )
    fig.add_vrect(x0=-2, x1=2, fillcolor="green", opacity=0.06, line_width=0)
    fig.add_vline(x=2, line_dash="dash", line_color="red", line_width=0.7)
    fig.add_vline(x=-2, line_dash="dash", line_color="red", line_width=0.7)
    fig.add_vline(x=0, line_dash="dot", line_color="gray", line_width=0.5)
    fig.update_layout(
        xaxis_title="Infit ZSTD", yaxis_title="Measure (logits)",
        title="Pathway Map: Measure vs Infit ZSTD", height=500,
    )
    st.plotly_chart(fig, width="stretch")
    render_chart_guide("pathway_map")


def _draw_facet_distribution_plotly(diagnostics: dict) -> None:
    """Interactive Plotly box + strip plot of facet distributions."""
    st.subheader("Facet Element Distribution")
    st.caption("Distribution of estimated measures within each facet.")

    measures = diagnostics.get("measures", pd.DataFrame())
    if measures.empty or "Facet" not in measures.columns or "Estimate" not in measures.columns:
        st.info("Facet measures not available.")
        return

    pdf = measures.copy()
    pdf["Estimate"] = pd.to_numeric(pdf["Estimate"], errors="coerce")
    pdf = pdf.dropna(subset=["Estimate"])

    hover_data = ["Level"] if "Level" in pdf.columns else None
    fig = px.box(
        pdf, x="Facet", y="Estimate", color="Facet",
        points="all", hover_data=hover_data,
        color_discrete_sequence=px.colors.qualitative.Set2,
    )
    fig.update_layout(
        yaxis_title="Measure (logits)",
        title="Facet Element Distributions",
        showlegend=False, height=450,
    )
    st.plotly_chart(fig, width="stretch")
    render_chart_guide("facet_distribution")


def _draw_wright_map_plotly(
    person_tbl: pd.DataFrame, facet_tbl: pd.DataFrame, step_tbl: pd.DataFrame,
) -> None:
    """Interactive Plotly Wright Map: person histogram (left) + facet dot plot (right)."""
    person_est = pd.to_numeric(
        person_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce"
    ).dropna()
    if person_est.empty:
        st.caption("No finite person estimates for Wright Map.")
        return

    facet_est = facet_tbl.copy() if facet_tbl is not None else pd.DataFrame()
    if "Estimate" in facet_est.columns:
        facet_est["Estimate"] = pd.to_numeric(facet_est["Estimate"], errors="coerce")
        facet_est = facet_est.dropna(subset=["Estimate"])

    facet_names = list(facet_est["Facet"].unique()) if "Facet" in facet_est.columns else []
    max_elements_per_facet = int(facet_est.groupby("Facet").size().max()) if "Facet" in facet_est.columns and not facet_est.empty else 0
    label_max = (
        int(facet_est.get("Level", pd.Series(dtype=str)).astype(str).str.len().max())
        if "Level" in facet_est.columns and not facet_est.empty else 0
    )
    min_label_gap = _minimum_within_facet_logit_gap(facet_est)
    tight_labels = min_label_gap < 0.30
    crowded = max_elements_per_facet > 8 or len(facet_names) > 4 or label_max > 18 or tight_labels
    requested_direct_labels = st.checkbox(
        "Show Wright map point labels directly on plot",
        value=not crowded,
        key="wright_map_show_direct_labels_tight" if tight_labels else "wright_map_show_direct_labels",
        disabled=tight_labels,
        help=(
            "Turn this off for dense designs. Full element labels remain available in hover text, "
            "which prevents overlapping plot labels."
        ),
    )
    show_direct_labels = bool(requested_direct_labels and not tight_labels)
    if crowded and not show_direct_labels:
        st.caption("Dense or tightly spaced Wright map: direct labels are hidden to prevent overlap. Hover points to read full labels.")

    fig = make_subplots(
        rows=1, cols=2, column_widths=[0.3, 0.7],
        shared_yaxes=True,
        subplot_titles=["Persons", "Facet & step locations"],
    )

    # Left: person histogram (horizontal)
    fig.add_trace(go.Histogram(
        y=person_est.values, nbinsy=30,
        marker_color="#b0b0b0", name="Persons",
    ), row=1, col=1)
    fig.update_xaxes(autorange="reversed", title_text="Count", row=1, col=1)

    # Right: facet element dots
    colors = px.colors.qualitative.Set2
    for i, fname in enumerate(facet_names):
        fdata = facet_est[facet_est["Facet"] == fname]
        full_labels = fdata["Level"].astype(str).values if "Level" in fdata.columns else np.array([str(idx) for idx in fdata.index])
        show_text = show_direct_labels and len(fdata) <= 25
        fig.add_trace(go.Scatter(
            x=[fname] * len(fdata),
            y=fdata["Estimate"].values,
            mode="markers+text" if show_text else "markers",
            marker=dict(size=8, color=colors[i % len(colors)]),
            text=_compact_label_list(full_labels, max_chars=18) if show_text else None,
            textposition="middle right", textfont=dict(size=9),
            name=fname,
            customdata=np.column_stack([full_labels, np.repeat(fname, len(fdata))]),
            hovertemplate="%{customdata[1]}: %{customdata[0]}<br>Logit=%{y:.2f}<extra></extra>",
        ), row=1, col=2)

    # Step thresholds
    if step_tbl is not None and not step_tbl.empty:
        step_vals = pd.to_numeric(
            step_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce"
        ).dropna()
        for sv in step_vals:
            fig.add_hline(y=float(sv), line_dash="dot", line_color="#d95f02", line_width=0.6, row=1, col=2)

    fig.update_yaxes(title_text="Logit scale", row=1, col=1)
    fig.update_layout(
        height=max(550, 22 * max_elements_per_facet + 220 if show_direct_labels else 550),
        hovermode="closest",
        margin=_readable_plot_margins(
            x_labels=[str(v) for v in facet_names],
            base_left=90,
            base_bottom=90,
        ),
    )
    facet_tick_angle = (
        -30 if len(facet_names) > 4
        or max((len(str(v)) for v in facet_names), default=0) > 12
        else 0
    )
    fig.update_xaxes(
        tickangle=facet_tick_angle,
        automargin=True,
        row=1,
        col=2,
    )
    st.plotly_chart(fig, width="stretch")


def _draw_observed_vs_expected(diagnostics: dict) -> None:
    """Observed vs expected score diagnostic plot."""


    st.subheader("Observed vs Expected Scores")
    st.caption(
        "Points along the diagonal indicate good model fit. Systematic deviation "
        "from the diagonal suggests model misspecification."
    )

    obs_df = diagnostics.get("obs")
    if obs_df is None or obs_df.empty:
        st.info("Observation data not available.")
        return

    if "Expected" not in obs_df.columns or "Observed" not in obs_df.columns:
        st.info("Expected/Observed columns not found in diagnostics.")
        return

    expected = pd.to_numeric(obs_df["Expected"], errors="coerce")
    observed = pd.to_numeric(obs_df["Observed"], errors="coerce")
    mask = expected.notna() & observed.notna()

    if mask.sum() < 10:
        st.info("Too few valid observations for this plot.")
        return

    # Bin expected scores for cleaner visualization
    n_bins = min(30, int(np.sqrt(mask.sum())))
    exp_vals = expected[mask].values
    obs_vals = observed[mask].values

    bin_edges = np.linspace(exp_vals.min(), exp_vals.max(), n_bins + 1)
    bin_idx = np.digitize(exp_vals, bin_edges[1:-1])
    bin_exp = []
    bin_obs = []
    bin_n = []
    for b in range(n_bins):
        sel = bin_idx == b
        if sel.sum() > 0:
            bin_exp.append(float(exp_vals[sel].mean()))
            bin_obs.append(float(obs_vals[sel].mean()))
            bin_n.append(int(sel.sum()))

    lo = min(min(bin_exp), min(bin_obs))
    hi = max(max(bin_exp), max(bin_obs))
    margin = (hi - lo) * 0.05
    sizes = np.array(bin_n)
    sizes_scaled = 8 + 30 * sizes / sizes.max()

    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=[lo - margin, hi + margin], y=[lo - margin, hi + margin],
        mode="lines", line=dict(dash="dash", color="#999", width=1),
        name="Perfect fit",
    ))
    fig.add_trace(go.Scatter(
        x=bin_exp, y=bin_obs, mode="markers",
        marker=dict(size=sizes_scaled, color="#1b9e77", opacity=0.7,
                    line=dict(color="white", width=0.5)),
        name="Observed", customdata=bin_n,
        hovertemplate="Expected: %{x:.2f}<br>Observed: %{y:.2f}<br>n=%{customdata}<extra></extra>",
    ))
    fig.update_layout(
        xaxis_title="Expected Score (model)", yaxis_title="Observed Score (actual)",
        title="Observed vs Expected Scores", height=480, template="plotly_white",
        yaxis=dict(scaleanchor="x", scaleratio=1),
    )
    st.plotly_chart(fig, width="stretch")


