def _self_test_apa_reference_list() -> None:
    """Pin the APA 7 reference library to the narrative conventions used here."""
    # Library is well-formed
    _self_test_assert(
        len(_APA_REFERENCE_LIBRARY) >= 30,
        f"APA library should have ≥30 entries, has {len(_APA_REFERENCE_LIBRARY)}",
    )
    # Citation-to-key map is consistent with the library
    for citation, key in _CITATION_TO_KEY.items():
        _self_test_assert(
            key in _APA_REFERENCE_LIBRARY,
            f"citation map points at missing library key: {citation} -> {key}",
        )
    # Returned entries are alphabetised and deduplicated
    narrative = (
        "Estimation follows Masters (1982) (Masters, 1982) and uses the "
        "EM algorithm of (Bock & Aitkin, 1981). Fit interpretation follows "
        "(Linacre, 2002) and (Wright & Linacre, 1994). (Masters, 1982) again."
    )
    refs = build_apa_reference_list(narrative)
    _self_test_assert(len(refs) == 4, f"expected 4 unique refs, got {len(refs)}")
    _self_test_assert(refs == sorted(refs), "reference list is not alphabetised")
    # Always-include injection works even when the citation is not in the text
    refs2 = build_apa_reference_list("No citations here.", always_include=["Andrich_1978"])
    _self_test_assert(len(refs2) == 1, "always_include failed to inject")
    _self_test_assert("Andrich, D. (1978)" in refs2[0], "always_include returned wrong entry")
    # Unknown citations are silently ignored rather than erroring
    refs3 = build_apa_reference_list("(NotACitedAuthor, 9999)")
    _self_test_assert(refs3 == [], "unknown citations must be ignored")


def export_reference_parity_fixture(output_dir: str) -> int:
    """Export deterministic Python outputs for external TAM/sirt/mirt checks."""
    out_dir = Path(output_dir).expanduser().resolve()
    out_dir.mkdir(parents=True, exist_ok=True)
    data = sample_mfrm_data(seed=20260411)
    keep_persons = data["Person"].drop_duplicates().head(8)
    data = data[data["Person"].isin(keep_persons)].copy()
    data_path = out_dir / "mfrm_parity_data_long.csv"
    data.to_csv(data_path, index=False)

    persons = data["Person"].drop_duplicates().astype(str).tolist()
    person_data = pd.DataFrame({
        "Person": persons,
        "Grade": [1 + (i // 2) for i in range(len(persons))],
        "Group": ["A" if i % 2 == 0 else "B" for i in range(len(persons))],
    })
    person_data_path = out_dir / "mfrm_parity_person_data.csv"
    person_data.to_csv(person_data_path, index=False)

    sirt_long = data.copy()
    sirt_long["SirtItem"] = sirt_long["Task"].astype(str) + "__" + sirt_long["Criterion"].astype(str)
    sirt_response = sirt_long.pivot_table(
        index=["Person", "Rater"],
        columns="SirtItem",
        values="Score",
        aggfunc="first",
    )
    sirt_item_cols = sorted(map(str, sirt_response.columns))
    sirt_response = sirt_response.reindex(columns=sirt_item_cols).reset_index()
    sirt_response.to_csv(out_dir / "sirt_rater_facets_response.csv", index=False)
    sirt_item_metadata = (
        sirt_long[["SirtItem", "Task", "Criterion"]]
        .drop_duplicates()
        .set_index("SirtItem")
        .loc[sirt_item_cols]
        .reset_index()
    )
    sirt_item_metadata.to_csv(out_dir / "sirt_rater_facets_items.csv", index=False)

    scenarios = [
        {
            "name": "jmle_rsm",
            "method": "JMLE",
            "model": "RSM",
            "mml_engine": "EM",
            "population_formula": None,
            "person_data": None,
        },
        {
            "name": "jmle_pcm_task_steps",
            "method": "JMLE",
            "model": "PCM",
            "mml_engine": "EM",
            "step_facet": "Task",
            "population_formula": None,
            "person_data": None,
        },
        {
            "name": "mml_rsm_fixed_prior",
            "method": "MML",
            "model": "RSM",
            "mml_engine": "EM",
            "population_formula": None,
            "person_data": None,
        },
        {
            "name": "mml_rsm_latent_regression",
            "method": "MML",
            "model": "RSM",
            "mml_engine": "EM",
            "population_formula": "~ Grade + Group",
            "person_data": person_data,
        },
        {
            "name": "mml_gpcm_task_steps",
            "method": "MML",
            "model": "GPCM",
            "mml_engine": "EM",
            "step_facet": "Task",
            "slope_facet": "Task",
            "population_formula": None,
            "person_data": None,
        },
    ]
    manifest_rows = []
    for scenario in scenarios:
        res = mfrm_estimate(
            data,
            person_col="Person",
            facet_cols=["Rater", "Task", "Criterion"],
            score_col="Score",
            model=scenario["model"],
            method=scenario["method"],
            step_facet=scenario.get("step_facet"),
            slope_facet=scenario.get("slope_facet"),
            mml_engine=scenario["mml_engine"],
            quad_points=7,
            population_prior_sd=1.0,
            maxit=60,
            reltol=1e-5,
            person_data=scenario["person_data"],
            person_id_col="Person" if scenario["person_data"] is not None else None,
            population_formula=scenario["population_formula"],
            population_standardize_numeric=True if scenario["population_formula"] else False,
            compute_plausible_values=scenario["method"] == "MML",
            n_plausible_values=3,
            plausible_seed=20260411,
        )
        diagnostics = mfrm_diagnostics(res, compute_pca=True, compute_marginal=scenario["method"] == "MML")
        prefix = scenario["name"]
        frames = {
            "summary": res.get("summary", pd.DataFrame()),
            "convergence": res.get("convergence", pd.DataFrame()),
            "person_measures": res.get("facets", {}).get("person", pd.DataFrame()),
            "facet_measures": res.get("facets", {}).get("others", pd.DataFrame()),
            "steps": res.get("steps", pd.DataFrame()),
            "gpcm_slopes": res.get("slopes", pd.DataFrame()),
            "population_coefficients": res.get("population", {}).get("coefficients", pd.DataFrame()),
            "population_person_data": res.get("population", {}).get("person_data", pd.DataFrame()),
            "posterior_scores": res.get("posterior", {}).get("scores", pd.DataFrame()),
            "fit_statistics": diagnostics.get("fit", pd.DataFrame()),
            "reliability": diagnostics.get("reliability", pd.DataFrame()),
            "score_map": res.get("prep", {}).get("score_map", pd.DataFrame()),
        }
        written = []
        for key, frame in frames.items():
            if isinstance(frame, pd.DataFrame) and not frame.empty:
                file_name = f"{prefix}_{key}.csv"
                frame.to_csv(out_dir / file_name, index=False)
                written.append(file_name)
        summary = res.get("summary", pd.DataFrame())
        manifest_rows.append({
            "Scenario": prefix,
            "Method": scenario["method"],
            "Model": scenario["model"],
            "StepFacet": scenario.get("step_facet"),
            "SlopeFacet": scenario.get("slope_facet"),
            "MmlEngine": res.get("config", {}).get("mml_engine"),
            "PopulationFormula": scenario["population_formula"] or "",
            "LogLik": float(summary["LogLik"].iloc[0]) if isinstance(summary, pd.DataFrame) and not summary.empty else np.nan,
            "Converged": bool(summary["Converged"].iloc[0]) if isinstance(summary, pd.DataFrame) and not summary.empty else False,
            "Files": ";".join(written),
        })
    pd.DataFrame(manifest_rows).to_csv(out_dir / "python_parity_manifest.csv", index=False)
    cross_package_validation_plan().to_csv(out_dir / "cross_package_validation_plan.csv", index=False)
    cross_package_parameterization_notes().to_csv(out_dir / "cross_package_parameterization_notes.csv", index=False)
    cross_package_tolerance_policy().to_csv(out_dir / "cross_package_tolerance_policy.csv", index=False)
    external_reference_documentation_table().to_csv(out_dir / "external_reference_documentation.csv", index=False)
    external_simulation_reference_inventory().to_csv(out_dir / "external_simulation_reference_inventory.csv", index=False)
    external_simulation_template_inventory().to_csv(out_dir / "external_simulation_template_inventory.csv", index=False)
    external_validation_artifact_checklist().to_csv(out_dir / "external_validation_artifact_checklist.csv", index=False)
    external_validation_report_template().to_csv(out_dir / "external_validation_report_template.csv", index=False)
    mfrmr_015_migration_coverage_table().to_csv(out_dir / "mfrmr_015_migration_coverage.csv", index=False)
    for name, script_text in external_simulation_template_scripts().items():
        (out_dir / name).write_text(script_text, encoding="utf-8")

    readme = """# MFRM Python Parity Fixture

This folder contains deterministic Python outputs for external comparison with
TAM, sirt, mirt, FACETS, or ConQuest. The goal is not to claim exact parameter
identity across all packages. Use it to separate expected parameterisation
differences from implementation regressions.

Files:
- `mfrm_parity_data_long.csv`: long-format data fitted by the Python app.
- `mfrm_parity_person_data.csv`: person-level covariates for latent regression.
- `sirt_rater_facets_response.csv` and `sirt_rater_facets_items.csv`: wide
  person-rater response matrix plus item metadata for a direct `sirt::rm.facets`
  rater-facet smoke check.
- `python_parity_manifest.csv`: scenario index and Python log-likelihoods.
- `cross_package_validation_plan.csv`: what to compare with TAM, sirt, mirt,
  FACETS-like, and ConQuest-style reference workflows.
- `cross_package_parameterization_notes.csv`: conventions to align before
  numerical comparisons.
- `cross_package_tolerance_policy.csv`: default review thresholds.
- `external_reference_documentation.csv`: official documentation touchpoints
  used to scope optional validation.
- `external_simulation_reference_inventory.csv`: local Simulation-directory
  artifacts that can support numerical validation without becoming runtime
  dependencies or bundled private data.
- `external_simulation_template_inventory.csv`: index of sanitized Python/R/Julia
  handoff templates for optional external validation.
- `README_external_simulation_templates.md`,
  `simulation_validation_python_template.py`,
  `simulation_validation_r_template.R`, and
  `simulation_validation_julia_template.jl`: optional sanitized handoff scripts.
- `external_validation_artifact_checklist.csv`: artifacts to archive before
  making public comparison claims.
- `external_validation_report_template.csv`: blank reviewer table for the
  final external validation summary.
- `mfrmr_015_migration_coverage.csv`: migration coverage map for the local
  mfrmr 0.1.5 feature surface.
- `*_summary.csv`, `*_person_measures.csv`, `*_facet_measures.csv`, `*_steps.csv`:
  Python reference outputs for each scenario.
- `r_crosscheck_scaffold.R`: optional R script. It is not used by the
  Streamlit app at runtime.

Comparison rules:
- JMLE RSM/PCM is closest to FACETS-style fixed-effect estimation, but optimizer
  and constraints can still differ.
- MML RSM is closest to TAM/ConQuest-style MML, except this app fixes the prior
  SD through `population_prior_sd` rather than estimating the latent variance.
- sirt `rm.facets()` is closest for rater-facet MML with optional slopes.
- mirt is useful for broad IRT checks such as GPCM, EAP/factor scores, and
  plausible values, but it does not natively decompose arbitrary MFRM facets in
  the same long-format layout.
- Individual plausible-value draws are not expected to match; compare
  distributions and downstream regression trends.
- Strict marginal diagnostics and package residual diagnostics are screening
  evidence, not proof of model truth.
- The Python app should be described as covering the listed mfrmr 0.1.5
  migration areas with documented boundaries, not as a runtime wrapper around
  mfrmr.

Suggested tolerance policy:
- Exact row counts, category support, and missingness flags should match.
- Log-likelihood and parameter differences should be reviewed with package-
  specific constraints documented; start with absolute differences <= 0.05 logits
  for comparable centered fixed-effect measures and relax only with justification.
- Do not compare unconstrained slopes, latent variances, or anchoring constants
  as if they were the same parameter without a parameterization map.

Optional R handoff:
1. Run `Rscript r_crosscheck_scaffold.R` from this folder.
2. Review `r_crosscheck_status.csv`, `r_crosscheck_package_versions.csv`, and
   `r_crosscheck_report.md`.
3. Copy supported findings into `external_validation_report_template.csv`.
4. Keep rows marked `missing` or `error` out of public validation claims.
"""
    (out_dir / "README.md").write_text(readme, encoding="utf-8")

    r_script = """# External R cross-check scaffold for the MFRM Python parity fixture.
# Run from this folder after installing any packages you want to compare:
# install.packages(c("TAM", "sirt", "mirt", "tidyr", "dplyr"))

status <- data.frame(
  Package = character(),
  Check = character(),
  Status = character(),
  Detail = character(),
  LogLik = numeric(),
  stringsAsFactors = FALSE
)

record_status <- function(package, check, status_value, detail, logLik = NA_real_) {
  status <<- rbind(
    status,
    data.frame(
      Package = package,
      Check = check,
      Status = status_value,
      Detail = detail,
      LogLik = as.numeric(logLik),
      stringsAsFactors = FALSE
    )
  )
}

package_version_text <- function(package) {
  if (!requireNamespace(package, quietly = TRUE)) {
    return(NA_character_)
  }
  as.character(utils::packageVersion(package))
}

package_versions <- data.frame(
  Package = c("R", "TAM", "sirt", "mirt", "tidyr", "dplyr"),
  Version = c(
    paste(R.version$major, R.version$minor, sep = "."),
    package_version_text("TAM"),
    package_version_text("sirt"),
    package_version_text("mirt"),
    package_version_text("tidyr"),
    package_version_text("dplyr")
  ),
  Installed = c(
    TRUE,
    requireNamespace("TAM", quietly = TRUE),
    requireNamespace("sirt", quietly = TRUE),
    requireNamespace("mirt", quietly = TRUE),
    requireNamespace("tidyr", quietly = TRUE),
    requireNamespace("dplyr", quietly = TRUE)
  ),
  stringsAsFactors = FALSE
)
write.csv(package_versions, "r_crosscheck_package_versions.csv", row.names = FALSE)

dat <- read.csv("mfrm_parity_data_long.csv")
person_data <- read.csv("mfrm_parity_person_data.csv")
manifest <- read.csv("python_parity_manifest.csv")

if (requireNamespace("tidyr", quietly = TRUE) && requireNamespace("dplyr", quietly = TRUE)) {
  suppressPackageStartupMessages(library(dplyr))
  suppressPackageStartupMessages(library(tidyr))
  wide <- dat |>
    mutate(item_id = paste(Rater, Task, Criterion, sep = "_")) |>
    select(Person, item_id, Score) |>
    pivot_wider(id_cols = Person, names_from = item_id, values_from = Score)
  resp <- as.matrix(wide[, -1])
  rownames(resp) <- wide$Person
  facets <- dat |>
    distinct(Rater, Task, Criterion) |>
    mutate(item_id = paste(Rater, Task, Criterion, sep = "_"))

  if (requireNamespace("TAM", quietly = TRUE)) {
    message("TAM cross-check: MML/facet design reference, not exact Python parity.")
    tam_result <- tryCatch({
      tam_mod <- TAM::tam.mml.mfr(
        resp = resp,
        facets = facets[, c("Rater", "Task", "Criterion")],
        formulaA = ~ item + Rater + Task + Criterion + step,
        pid = wide$Person,
        control = list(maxiter = 120, progress = FALSE)
      )
      write.csv(tam_mod$xsi.facets, "tam_xsi_facets.csv", row.names = FALSE)
      write.csv(tam_mod$person, "tam_person.csv", row.names = FALSE)
      tam_loglik <- if (!is.null(tam_mod$deviance)) -0.5 * tam_mod$deviance else NA_real_
      record_status("TAM", "tam.mml.mfr", "ok", "Wrote tam_xsi_facets.csv and tam_person.csv", tam_loglik)
      TRUE
    }, error = function(e) {
      record_status("TAM", "tam.mml.mfr", "error", conditionMessage(e), NA_real_)
      FALSE
    })
  } else {
    record_status("TAM", "tam.mml.mfr", "missing", "Package TAM is not installed", NA_real_)
  }

  if (requireNamespace("mirt", quietly = TRUE)) {
    message("mirt cross-check: item-level GPCM check, not arbitrary-facet decomposition.")
    mirt_result <- tryCatch({
      resp0 <- resp - min(dat$Score, na.rm = TRUE)
      mirt_mod <- mirt::mirt(resp0, 1, itemtype = "gpcm", verbose = FALSE, technical = list(NCYCLES = 100))
      write.csv(as.data.frame(mirt::fscores(mirt_mod, method = "EAP")), "mirt_gpcm_eap_scores.csv")
      write.csv(as.data.frame(mirt::coef(mirt_mod, simplify = TRUE)$items), "mirt_gpcm_item_parameters.csv")
      mirt_loglik <- tryCatch(as.numeric(mirt_mod@Fit$logLik), error = function(e) NA_real_)
      record_status("mirt", "gpcm item-level", "ok", "Wrote mirt_gpcm_eap_scores.csv and mirt_gpcm_item_parameters.csv", mirt_loglik)
      TRUE
    }, error = function(e) {
      record_status("mirt", "gpcm item-level", "error", conditionMessage(e), NA_real_)
      FALSE
    })
  } else {
    record_status("mirt", "gpcm item-level", "missing", "Package mirt is not installed", NA_real_)
  }
} else {
  record_status("tidyr/dplyr", "wide data build", "missing", "Install tidyr and dplyr to run R cross-checks", NA_real_)
}

if (requireNamespace("sirt", quietly = TRUE)) {
  message("sirt cross-check: direct rater-facet smoke check with person-rater rows.")
  sirt_result <- tryCatch({
    sirt_resp <- read.csv("sirt_rater_facets_response.csv", check.names = FALSE)
    sirt_items <- read.csv("sirt_rater_facets_items.csv", check.names = FALSE)
    sirt_pid <- sirt_resp$Person
    sirt_rater <- as.character(sirt_resp$Rater)
    sirt_dat <- as.matrix(sirt_resp[, setdiff(names(sirt_resp), c("Person", "Rater")), drop = FALSE])
    storage.mode(sirt_dat) <- "numeric"
    sirt_dat <- sirt_dat - min(sirt_dat, na.rm = TRUE)
    if (!all(colnames(sirt_dat) %in% sirt_items$SirtItem)) {
      stop("sirt item metadata does not cover all response columns")
    }
    sirt_fit_log <- capture.output({
      sirt_mod <- sirt::rm.facets(
        dat = sirt_dat,
        pid = sirt_pid,
        rater = sirt_rater,
        est.b.rater = TRUE,
        est.a.item = FALSE,
        est.a.rater = FALSE,
        rater_item_int = FALSE,
        maxiter = 60
      )
    })
    saveRDS(sirt_mod, "sirt_rater_facets_model.rds")
    writeLines(sirt_fit_log, "sirt_rater_facets_fit_log.txt")
    writeLines(capture.output(print(summary(sirt_mod))), "sirt_rater_facets_summary.txt")
    sirt_loglik <- tryCatch({
      raw_loglik <- as.numeric(sirt_mod$ic$loglike)
      if (length(raw_loglik) == 0) NA_real_ else raw_loglik[1]
    }, error = function(e) NA_real_)
    record_status("sirt", "rm.facets rater fixture", "ok", "Wrote sirt_rater_facets_model.rds, fit log, and summary text", sirt_loglik)
    TRUE
  }, error = function(e) {
    record_status("sirt", "rm.facets rater fixture", "error", conditionMessage(e), NA_real_)
    FALSE
  })
} else {
  record_status("sirt", "rm.facets rater fixture", "missing", "Package sirt is not installed", NA_real_)
}

write.csv(status, "r_crosscheck_status.csv", row.names = FALSE)

report <- c(
  "# R Cross-Check Status",
  "",
  "This report records whether the generated parity fixture can be fitted by selected R packages.",
  "Use the outputs for directional checks only; exact equality is not expected because parameterisation, constraints, and latent variance handling differ.",
  "",
  "Package versions:",
  paste(capture.output(print(package_versions)), collapse = "\n"),
  "",
  paste(capture.output(print(status)), collapse = "\n"),
  "",
  "Python manifest:",
  paste(capture.output(print(manifest[, c('Scenario', 'Method', 'Model', 'LogLik', 'Converged')])), collapse = "\n")
)
writeLines(report, "r_crosscheck_report.md")

created_files <- list.files(pattern = "^(tam_|mirt_|sirt_|r_crosscheck_|external_|cross_package_|mfrmr_|python_|mfrm_|README)")
file_manifest <- data.frame(
  File = created_files,
  Bytes = file.info(created_files)$size,
  stringsAsFactors = FALSE
)
write.csv(file_manifest, "r_crosscheck_file_manifest.csv", row.names = FALSE)
message("Wrote r_crosscheck_status.csv, r_crosscheck_package_versions.csv, and r_crosscheck_report.md")
"""
    (out_dir / "r_crosscheck_scaffold.R").write_text(r_script, encoding="utf-8")
    print(f"Wrote parity fixture to: {out_dir}")
    print("Key files: mfrm_parity_data_long.csv, python_parity_manifest.csv, external_validation_report_template.csv, r_crosscheck_scaffold.R")
    return 0


def build_demo_report_frames(
    result: dict,
    diagnostics: dict,
    data: pd.DataFrame,
    all_bias_results: dict | None = None,
) -> OrderedDict[str, pd.DataFrame]:
    """Assemble beginner-facing demo report tables for CLI export."""
    frames: OrderedDict[str, pd.DataFrame] = OrderedDict()
    frames["demo_manifest"] = pd.DataFrame([
        {
            "AppVersion": APP_VERSION,
            "ReleaseLabel": APP_RELEASE_LABEL,
            "Dataset": "built-in synthetic sample",
            "Model": result.get("config", {}).get("model"),
            "Method": result.get("config", {}).get("method"),
            "RuntimeBoundary": "standalone Python; no mfrmr/rpy2/Rscript/FACETS/TAM/sirt/mirt runtime call",
            "PrivacyNote": "The demo uses synthetic built-in data only.",
            "ReadFirst": "Open publication_gate_summary, then submission_action_plan, then beginner_case_guidance, then final_report_readiness, then manuscript_claim_guide, then manuscript_template.md, then visual_interpretation_checklist, then measures and category_probability_curves.",
        }
    ])
    frames["sample_data"] = data.copy()
    summary = result.get("summary", pd.DataFrame())
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        frames["summary"] = summary
    convergence = result.get("convergence", pd.DataFrame())
    if isinstance(convergence, pd.DataFrame) and not convergence.empty:
        frames["convergence"] = convergence
    prep = result.get("prep", {})
    score_map = prep.get("score_map", pd.DataFrame())
    if isinstance(score_map, pd.DataFrame) and not score_map.empty:
        frames["score_map"] = score_map
    publication_gate = build_publication_gate_summary(result, diagnostics, all_bias_results or {})
    if isinstance(publication_gate, pd.DataFrame) and not publication_gate.empty:
        frames["publication_gate_summary"] = publication_gate
    action_plan = build_submission_action_plan(result, diagnostics, all_bias_results or {})
    if isinstance(action_plan, pd.DataFrame) and not action_plan.empty:
        frames["submission_action_plan"] = action_plan
    beginner_cases = build_beginner_case_guidance(result, diagnostics, all_bias_results or {})
    if isinstance(beginner_cases, pd.DataFrame) and not beginner_cases.empty:
        frames["beginner_case_guidance"] = beginner_cases
    readiness = build_final_report_readiness(result, diagnostics, all_bias_results or {})
    if isinstance(readiness, pd.DataFrame) and not readiness.empty:
        frames["final_report_readiness"] = readiness
    claim_guide = build_manuscript_claim_guide(result, diagnostics, all_bias_results or {})
    if isinstance(claim_guide, pd.DataFrame) and not claim_guide.empty:
        frames["manuscript_claim_guide"] = claim_guide
    frames["visual_interpretation_checklist"] = visual_interpretation_checklist()
    frames["visual_method_evidence"] = visual_method_evidence_table()
    frames["public_beta_limitations"] = public_beta_limitations_table()
    frames["external_simulation_reference_inventory"] = external_simulation_reference_inventory()
    frames["external_simulation_template_inventory"] = external_simulation_template_inventory()
    frames["mfrmr_015_migration_coverage"] = mfrmr_015_migration_coverage_table()
    frames["public_release_readiness"] = public_release_readiness_table()
    person = result.get("facets", {}).get("person", pd.DataFrame())
    if isinstance(person, pd.DataFrame) and not person.empty:
        frames["person_measures"] = person
    others = result.get("facets", {}).get("others", pd.DataFrame())
    if isinstance(others, pd.DataFrame) and not others.empty:
        frames["facet_measures"] = others
    steps = result.get("steps", pd.DataFrame())
    if isinstance(steps, pd.DataFrame) and not steps.empty:
        frames["steps"] = steps
    slopes = result.get("slopes", pd.DataFrame())
    if isinstance(slopes, pd.DataFrame) and not slopes.empty:
        frames["gpcm_slopes"] = slopes
    reliability = diagnostics.get("reliability", pd.DataFrame())
    if isinstance(reliability, pd.DataFrame) and not reliability.empty:
        frames["reliability"] = reliability
    fit = diagnostics.get("fit", pd.DataFrame())
    if isinstance(fit, pd.DataFrame) and not fit.empty:
        frames["fit_statistics"] = fit
    obs = diagnostics.get("obs", pd.DataFrame())
    if isinstance(obs, pd.DataFrame) and not obs.empty:
        frames["residuals"] = obs
        try:
            cat_stats = calc_category_stats(obs, result)
            if isinstance(cat_stats, pd.DataFrame) and not cat_stats.empty:
                frames["category_diagnostics"] = cat_stats
        except Exception:
            pass
    try:
        step_order = calc_step_order(result.get("steps", pd.DataFrame()))
        if isinstance(step_order, pd.DataFrame) and not step_order.empty:
            frames["step_order"] = step_order
    except Exception:
        pass
    curve_export = category_probability_curve_export_table(result)
    if isinstance(curve_export, pd.DataFrame) and not curve_export.empty:
        frames["category_probability_curves"] = curve_export
    try:
        predictions = compute_fitted_prediction_table(result)
        if isinstance(predictions, pd.DataFrame) and not predictions.empty:
            frames["fitted_predictions"] = predictions
    except Exception:
        pass
    for pair_key, bundle in (all_bias_results or {}).items():
        table = bundle.get("table") if isinstance(bundle, dict) else None
        summary_tbl = bundle.get("summary") if isinstance(bundle, dict) else None
        safe_pair = re.sub(r"[^A-Za-z0-9]+", "_", str(pair_key)).strip("_")[:40]
        if isinstance(table, pd.DataFrame) and not table.empty:
            frames[f"bias_{safe_pair}"] = table
        if isinstance(summary_tbl, pd.DataFrame) and not summary_tbl.empty:
            frames[f"bias_{safe_pair}_summary"] = summary_tbl
    return frames


def export_demo_report(output_dir: str) -> int:
    """Export a deterministic beginner-facing demo report from built-in sample data."""
    out_dir = Path(output_dir).expanduser().resolve()
    out_dir.mkdir(parents=True, exist_ok=True)
    data = sample_mfrm_data(seed=20260411)
    keep_persons = data["Person"].drop_duplicates().head(12)
    data = data[data["Person"].isin(keep_persons)].copy()
    data.to_csv(out_dir / "demo_sample_data.csv", index=False)

    result = mfrm_estimate(
        data,
        person_col="Person",
        facet_cols=["Rater", "Task", "Criterion"],
        score_col="Score",
        model="PCM",
        method="JMLE",
        step_facet="Task",
        maxit=80,
        reltol=1e-5,
    )
    diagnostics = mfrm_diagnostics(result, compute_pca=True, compute_marginal=False)
    all_bias_results: dict[str, dict] = {}
    try:
        all_bias_results["Rater x Task"] = estimate_bias_interaction(
            result,
            diagnostics,
            "Rater",
            "Task",
            max_abs=10.0,
            omit_extreme=True,
        )
    except Exception:
        all_bias_results = {}

    frames = build_demo_report_frames(result, diagnostics, data, all_bias_results=all_bias_results)
    method_appendix = generate_method_appendix_text(result, diagnostics, all_bias_results=all_bias_results)
    manuscript_template = generate_manuscript_reporting_template(result, diagnostics, all_bias_results=all_bias_results)
    for name, frame in frames.items():
        frame.to_csv(out_dir / f"{name}.csv", index=False)
    (out_dir / "MFRM_Demo_Report.xlsx").write_bytes(to_excel_bytes(frames))
    (out_dir / "MFRM_Demo_Report.html").write_bytes(to_html_report(frames, title="MFRM Demo Report"))
    (out_dir / "MFRM_Demo_Report.zip").write_bytes(build_osf_zip(
        frames,
        title="MFRM_Demo_Report",
        text_assets={
            "method_appendix.md": method_appendix,
            "manuscript_template.md": manuscript_template,
            **external_simulation_template_scripts(),
        },
    ))
    (out_dir / "method_appendix.md").write_text(method_appendix, encoding="utf-8")
    (out_dir / "manuscript_template.md").write_text(manuscript_template, encoding="utf-8")
    for name, script_text in external_simulation_template_scripts().items():
        (out_dir / name).write_text(script_text, encoding="utf-8")

    figure_html: dict[str, str] = {}
    figure_png: dict[str, bytes] = {}
    figure_measures = diagnostics.get("measures", pd.DataFrame())
    facets_data = result.get("facets", {})
    _add_figure_export(
        _make_wright_map_export_figure(
            facets_data.get("person", pd.DataFrame()),
            facets_data.get("others", pd.DataFrame()),
            result.get("steps", pd.DataFrame()),
        ),
        "wright_map",
        figure_png,
        figure_html,
    )
    _add_figure_export(
        _make_fit_scatter_export_figure(figure_measures),
        "fit_scatter",
        figure_png,
        figure_html,
    )
    _add_figure_export(
        _make_facet_distribution_export_figure(figure_measures),
        "facet_distribution",
        figure_png,
        figure_html,
    )
    curve_options = category_probability_curve_options(result)
    for row in curve_options.itertuples(index=False):
        is_average = bool(getattr(row, "IsAverage"))
        level_idx = None if is_average else int(getattr(row, "LevelIndex"))
        curve = build_category_probability_curve_data(result, step_level_index=level_idx)
        fig_curve, fig_expected = _make_category_probability_curve_figures(curve)
        safe_label = re.sub(r"[^A-Za-z0-9]+", "_", str(getattr(row, "Label"))).strip("_")[:80] or "curve"
        if fig_curve is not None:
            _add_figure_export(
                fig_curve,
                f"category_probability_curve_{safe_label}",
                figure_png,
                figure_html,
            )
        if fig_expected is not None:
            _add_figure_export(
                fig_expected,
                f"expected_score_curve_{safe_label}",
                figure_png,
                figure_html,
            )
    figure_manifest = _figure_export_manifest(figure_html, figure_png)
    if not figure_manifest.empty:
        figure_manifest.to_csv(out_dir / "figure_manifest.csv", index=False)
        figure_assets = _figure_bundle_assets(figure_html, figure_png, figure_manifest)
        (out_dir / "MFRM_Demo_Publication_Figures.zip").write_bytes(
            cached_mixed_asset_zip(figure_assets, bytes_mapping_fingerprint(figure_assets))
        )
    if figure_html:
        fig_dir = out_dir / "figures_html"
        fig_dir.mkdir(exist_ok=True)
        for name, html in figure_html.items():
            (fig_dir / f"{name}.html").write_text(html, encoding="utf-8")
        (out_dir / "MFRM_Demo_Figures_HTML.zip").write_bytes(cached_named_asset_zip(figure_html, bytes_mapping_fingerprint(figure_html), "html"))
    if figure_png:
        png_dir = out_dir / "figures_png"
        png_dir.mkdir(exist_ok=True)
        for name, png in figure_png.items():
            (png_dir / f"{name}.png").write_bytes(png)
        (out_dir / "MFRM_Demo_Figures_PNG.zip").write_bytes(cached_named_asset_zip(figure_png, bytes_mapping_fingerprint(figure_png), "png"))

    readme = f"""# MFRM Demo Report

This folder was generated from the app's built-in synthetic sample data.
It demonstrates the standalone Python workflow without calling `mfrmr`,
`rpy2`, `Rscript`, FACETS, TAM, sirt, or mirt at runtime.

## Files to open first

1. `MFRM_Demo_Report.html`: browser-readable table report.
2. `publication_gate_summary.csv`: whether APA-style conclusions are ready, caveated, or blocked.
3. `submission_action_plan.csv`: prioritized blockers, caveats, boundaries, and wording repairs before manuscript use.
4. `beginner_case_guidance.csv`: case-specific cautions for common beginner interpretation traps.
5. `final_report_readiness.csv`: what to resolve before final reporting.
6. `manuscript_claim_guide.csv`: what is safe to claim in a manuscript.
7. `manuscript_template.md`: Methods, Results, limitations, and reviewer preflight scaffold.
8. `visual_interpretation_checklist.csv`: how to read each plot.
9. `visual_method_evidence.csv`: methodological basis and readability rules for plots.
10. `public_beta_limitations.csv`: what this beta release supports and does not claim.
11. `external_simulation_reference_inventory.csv`: local Simulation-directory
   validation artifacts to consult without bundling private data.
12. `external_simulation_template_inventory.csv`: index of sanitized Python/R/Julia
   external validation templates.
13. `README_external_simulation_templates.md` and `simulation_validation_*`:
   sanitized handoff scripts for optional external validation.
14. `mfrmr_015_migration_coverage.csv`: how the local mfrmr 0.1.5 feature surface maps to this Python app.
15. `public_release_readiness.csv`: repository-level public release checklist.
16. `category_probability_curves.csv`: long-form PCM curve data for the
   averaged view and each Task level.
17. `figure_manifest.csv`: manuscript-use notes and available formats for exported figures.
18. `MFRM_Demo_Publication_Figures.zip`: publication-styled PNG/HTML figure bundle.
19. `figures_html/`: interactive publication-styled diagnostic figures.
20. `method_appendix.md`: reproducible method notes for this demo run.

## Demo model

- Model: PCM
- Estimation: JMLE
- Step facet: Task
- Observations: {len(data):,}
- App version: {APP_VERSION}

The data are synthetic, but the report structure is the same one to use with
real rating data. For confidential real data, run locally and remove direct
identifiers before upload or paste.
"""
    (out_dir / "README.md").write_text(readme, encoding="utf-8")
    print(f"Wrote demo report to: {out_dir}")
    print("Key files: MFRM_Demo_Report.html, MFRM_Demo_Report.xlsx, publication_gate_summary.csv, submission_action_plan.csv, beginner_case_guidance.csv, final_report_readiness.csv, manuscript_claim_guide.csv, manuscript_template.md, figure_manifest.csv, MFRM_Demo_Publication_Figures.zip, figures_html/")
    return 0


def _benchmark_data_subset(base: pd.DataFrame, n_persons: int) -> pd.DataFrame:
    keep_persons = base["Person"].drop_duplicates().head(int(n_persons))
    return base[base["Person"].isin(keep_persons)].copy()


def _benchmark_bias_scan(result: dict, diagnostics: dict, facet_cols: list[str], bias_mode: str) -> tuple[float, int]:
    if bias_mode == "Skip":
        return 0.0, 0
    pairs_available = list(combinations(["Person"] + list(facet_cols), 2))
    if bias_mode == "All facet pairs":
        pairs = pairs_available
    elif bias_mode == "Selected pair" and pairs_available:
        pairs = [pairs_available[0]]
    else:
        pairs = []
    start_time = time.perf_counter()
    n_tables = 0
    for facet_a, facet_b in pairs:
        try:
            bundle = estimate_bias_interaction(
                result,
                diagnostics,
                facet_a,
                facet_b,
                max_abs=10.0,
                omit_extreme=True,
            )
            table = bundle.get("table") if isinstance(bundle, dict) else None
            if isinstance(table, pd.DataFrame) and not table.empty:
                n_tables += 1
        except Exception:
            continue
    return float(time.perf_counter() - start_time), n_tables


def _version_tuple(version_text: str) -> tuple[int, ...]:
    parts = re.findall(r"\d+", str(version_text))
    return tuple(int(part) for part in parts[:3]) if parts else (0,)


def _version_meets_floor(version_text: str, floor_text: str) -> bool:
    observed = _version_tuple(version_text)
    floor = _version_tuple(floor_text)
    max_len = max(len(observed), len(floor))
    observed = observed + (0,) * (max_len - len(observed))
    floor = floor + (0,) * (max_len - len(floor))
    return observed >= floor


def run_doctor(json_output: bool = False) -> int:
    """Run lightweight environment checks for local support and CI."""
    rows = []

    def record(check: str, status: str, detail: str) -> None:
        rows.append({"Check": check, "Status": status, "Detail": detail})

    record(
        "app_version",
        "ok",
        f"{APP_RELEASE_LABEL} {APP_VERSION}; standalone Python; no external MFRM engine is called",
    )
    record(
        "python",
        "ok" if sys.version_info >= (3, 11) else "warn",
        sys.version.split()[0],
    )

    for package_name, floor in RUNTIME_PACKAGE_FLOORS.items():
        try:
            version_text = importlib_metadata.version(package_name)
            status = "ok" if _version_meets_floor(version_text, floor) else "warn"
            record(f"package:{package_name}", status, f"{version_text} (required >= {floor})")
        except importlib_metadata.PackageNotFoundError:
            record(f"package:{package_name}", "error", f"missing (required >= {floor})")

    for asset_name in BUNDLED_ANCHOR_ASSETS:
        try:
            path = _bundled_asset_path(asset_name)
            payload = get_bundled_asset_bytes(asset_name)
            status = "ok" if payload else "error"
            record(f"asset:{asset_name}", status, f"{len(payload)} bytes at {path.name}")
        except Exception as exc:
            record(f"asset:{asset_name}", "error", str(exc))

    try:
        sample = cached_sample_mfrm_data(seed=20240101)
        record("sample_data", "ok" if isinstance(sample, pd.DataFrame) and not sample.empty else "error", f"{getattr(sample, 'shape', None)}")
    except Exception as exc:
        record("sample_data", "error", str(exc))

    try:
        ns = load_core_namespace()
        required_names = ["mfrm_estimate", "mfrm_diagnostics", "read_flexible_table"]
        missing = [name for name in required_names if name not in ns]
        record("core_namespace", "ok" if not missing else "error", "missing: " + ", ".join(missing) if missing else f"{len(ns)} functions")
    except Exception as exc:
        record("core_namespace", "error", str(exc))

    record(
        "privacy_boundary",
        "ok",
        "uploaded/pasted rating data are not cached as resources; export-byte caches are bounded and short-lived",
    )
    record(
        "runtime_boundary",
        "ok",
        "mfrmr, rpy2, Rscript, FACETS, TAM, sirt, and mirt are not runtime dependencies",
    )

    if json_output:
        print(json.dumps(rows, indent=2, ensure_ascii=False))
    else:
        width = max(len(row["Check"]) for row in rows) if rows else 5
        for row in rows:
            print(f"[{row['Status'].upper():5}] {row['Check']:<{width}}  {row['Detail']}")

    return 1 if any(row["Status"] == "error" for row in rows) else 0


def run_release_check(json_output: bool = False) -> int:
    """Run static public-beta release readiness checks."""
    readiness = public_release_readiness_table()
    limitations = public_beta_limitations_table()
    migration = mfrmr_015_migration_coverage_table()
    simulation_inventory = external_simulation_reference_inventory()
    simulation_templates = external_simulation_template_inventory()
    payload = {
        "release_status": "public beta / research preview",
        "app_version": APP_VERSION,
        "release_label": APP_RELEASE_LABEL,
        "readiness": readiness.to_dict(orient="records"),
        "limitations": limitations.to_dict(orient="records"),
        "external_simulation_reference_inventory": simulation_inventory.to_dict(orient="records"),
        "external_simulation_template_inventory": simulation_templates.to_dict(orient="records"),
        "mfrmr_015_migration_coverage": migration.to_dict(orient="records"),
    }
    if json_output:
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"Release status: public beta / research preview ({APP_RELEASE_LABEL} {APP_VERSION})")
        print("\nReadiness checks:")
        width = max(len(str(v)) for v in readiness["Check"].tolist()) if not readiness.empty else 5
        for _, row in readiness.iterrows():
            print(f"[{str(row['Status']).upper():10}] {str(row['Check']):<{width}}  {row['Evidence']}")
            print(f"{'':13} {row['Action']}")
        print("\nPublic beta limitations:")
        for _, row in limitations.iterrows():
            print(f"- {row['Area']}: {row['PublicBetaStatus']} - {row['Boundary']}")
        print(f"\nExternal Simulation reference inventory rows: {len(simulation_inventory)}")
        print(f"\nExternal Simulation template rows: {len(simulation_templates)}")
        print(f"\nmfrmr 0.1.5 migration coverage rows: {len(migration)}")
    blocker_count = int((readiness["Status"].astype(str) == "Blocker").sum()) if "Status" in readiness.columns else 1
    return 1 if blocker_count else 0


def run_benchmarks(csv_path: str | None = None, quick: bool = False) -> int:
    """Run small benchmark snapshots without opening Streamlit."""
    base = sample_mfrm_data(seed=20260411)
    facet_cols = ["Rater", "Task", "Criterion"]
    scenarios = [
        {
            "Scenario": "small_fast_preview_jmle_rsm",
            "Persons": 6,
            "Model": "RSM",
            "Method": "JMLE",
            "AnalysisDepth": "Fast preview",
            "Maxit": 40,
            "Reltol": 1e-3,
            "QuadPoints": None,
        },
        {
            "Scenario": "medium_standard_jmle_rsm",
            "Persons": 15,
            "Model": "RSM",
            "Method": "JMLE",
            "AnalysisDepth": "Standard (recommended)",
            "Maxit": 40,
            "Reltol": 1e-3,
            "QuadPoints": None,
        },
        {
            "Scenario": "large_standard_jmle_rsm",
            "Persons": 30,
            "Model": "RSM",
            "Method": "JMLE",
            "AnalysisDepth": "Standard (recommended)",
            "Maxit": 40,
            "Reltol": 1e-3,
            "QuadPoints": None,
        },
        {
            "Scenario": "small_full_publication_mml_rsm",
            "Persons": 6,
            "Model": "RSM",
            "Method": "MML",
            "AnalysisDepth": "Full publication",
            "Maxit": 8,
            "Reltol": 1e-3,
            "QuadPoints": 5,
        },
        {
            "Scenario": "small_full_publication_mml_pcm",
            "Persons": 6,
            "Model": "PCM",
            "Method": "MML",
            "AnalysisDepth": "Full publication",
            "Maxit": 8,
            "Reltol": 1e-3,
            "QuadPoints": 5,
        },
        {
            "Scenario": "small_full_publication_mml_gpcm",
            "Persons": 6,
            "Model": "GPCM",
            "Method": "MML",
            "AnalysisDepth": "Full publication",
            "Maxit": 8,
            "Reltol": 1e-3,
            "QuadPoints": 5,
        },
        {
            "Scenario": "small_full_publication_mml_latent_regression",
            "Persons": 6,
            "Model": "RSM",
            "Method": "MML",
            "AnalysisDepth": "Full publication",
            "Maxit": 8,
            "Reltol": 1e-3,
            "QuadPoints": 5,
            "PopulationFormula": "~ Grade + Group",
        },
    ]
    if quick:
        keep_scenarios = {
            "small_fast_preview_jmle_rsm",
            "small_full_publication_mml_rsm",
        }
        scenarios = [scenario for scenario in scenarios if scenario["Scenario"] in keep_scenarios]
    rows = []
    for scenario in scenarios:
        data = _benchmark_data_subset(base, scenario["Persons"])
        person_data = None
        if scenario.get("PopulationFormula"):
            persons = data["Person"].drop_duplicates().astype(str).tolist()
            person_data = pd.DataFrame({
                "Person": persons,
                "Grade": [1 + (i // 2) for i in range(len(persons))],
                "Group": ["A" if i % 2 == 0 else "B" for i in range(len(persons))],
            })
        settings = resolve_analysis_depth_settings(
            scenario["AnalysisDepth"],
            scenario["Method"],
        )
        fit_start = time.perf_counter()
        result = mfrm_estimate(
            data,
            person_col="Person",
            facet_cols=facet_cols,
            score_col="Score",
            model=scenario["Model"],
            method=scenario["Method"],
            mml_engine="Auto (recommended)",
            quad_points=int(scenario["QuadPoints"] or 5),
            maxit=int(scenario["Maxit"]),
            reltol=float(scenario["Reltol"]),
            person_data=person_data,
            person_id_col="Person" if person_data is not None else None,
            population_formula=scenario.get("PopulationFormula"),
            compute_plausible_values=bool(settings["compute_plausible_values"]),
            n_plausible_values=int(settings["n_plausible_values"]),
            plausible_seed=int(settings["plausible_seed"]),
        )
        estimate_seconds = float(time.perf_counter() - fit_start)

        diag_start = time.perf_counter()
        diagnostics = mfrm_diagnostics(
            result,
            compute_pca=bool(settings["compute_residual_pca"]),
            compute_marginal=bool(settings["compute_strict_marginal"]),
            marginal_pairwise=bool(settings["strict_marginal_pairwise"]),
            marginal_max_pair_cells=int(settings["strict_marginal_max_pair_cells"]),
        )
        diagnostics_seconds = float(time.perf_counter() - diag_start)
        bias_seconds, bias_tables = _benchmark_bias_scan(
            result,
            diagnostics,
            facet_cols,
            settings["bias_mode"],
        )

        summary = result["summary"].iloc[0]
        rows.append({
            "Scenario": scenario["Scenario"],
            "AnalysisDepth": scenario["AnalysisDepth"],
            "Method": scenario["Method"],
            "Model": scenario["Model"],
            "Rows": int(len(data)),
            "Persons": int(data["Person"].nunique()),
            "FacetCount": int(len(facet_cols)),
            "Categories": int(result["config"]["n_cat"]),
            "Maxit": int(scenario["Maxit"]),
            "Reltol": float(scenario["Reltol"]),
            "QuadPoints": scenario["QuadPoints"],
            "PopulationFormula": scenario.get("PopulationFormula", ""),
            "MmlEngine": result["config"].get("mml_engine"),
            "ComputePCA": bool(settings["compute_residual_pca"]),
            "ComputeStrictMarginal": bool(settings["compute_strict_marginal"]),
            "StrictMarginalPairwise": bool(settings["strict_marginal_pairwise"]),
            "ComputePlausibleValues": bool(settings["compute_plausible_values"]),
            "PlausibleValues": int(settings["n_plausible_values"]),
            "BiasMode": settings["bias_mode"],
            "BiasTables": int(bias_tables),
            "EstimateSeconds": estimate_seconds,
            "DiagnosticsSeconds": diagnostics_seconds,
            "BiasSeconds": float(bias_seconds),
            "TotalSeconds": estimate_seconds + diagnostics_seconds + float(bias_seconds),
            "Converged": bool(summary.get("Converged", False)),
            "Iterations": int(summary.get("Iterations", 0) or 0),
            "GradientNorm": float(summary.get("GradientNorm", np.nan)),
            "LogLik": float(summary.get("LogLik", np.nan)),
        })

    out = pd.DataFrame(rows)
    display_cols = [
        "Scenario",
        "Rows",
        "Method",
        "Model",
        "AnalysisDepth",
        "MmlEngine",
        "EstimateSeconds",
        "DiagnosticsSeconds",
        "BiasSeconds",
        "TotalSeconds",
        "Converged",
        "Iterations",
        "GradientNorm",
    ]
    print(out[display_cols].to_string(index=False))
    if csv_path:
        csv_out_path = Path(csv_path).expanduser()
        csv_out_path.parent.mkdir(parents=True, exist_ok=True)
        out.to_csv(csv_out_path, index=False)
        print(f"\nWrote benchmark snapshot: {csv_out_path}")
    return 0


def run_self_tests() -> int:
    tests = [
        ("zero-count intermediate category support", _self_test_zero_count_category_support),
        ("non-consecutive score recode", _self_test_nonconsecutive_recode),
        ("explicit boundary gap support", _self_test_boundary_gap_support),
        ("fractional score rejection", _self_test_fractional_score_rejection),
        ("JMLE RSM, PCM, and GPCM smoke", _self_test_jmle_rsm_pcm_smoke),
        ("analytical gradient checks", _self_test_gradient_checks),
        ("analysis-depth preset smoke", _self_test_analysis_depth_presets),
        ("MML Auto posterior, PCM/GPCM, and strict marginal", _self_test_mml_auto_posterior_and_marginal),
        ("MML engine branches and negative inputs", _self_test_mml_engine_branches_and_negative_inputs),
        ("latent regression population_formula", _self_test_latent_regression_population_formula),
        ("prediction simulation and design evaluation", _self_test_prediction_simulation_design),
        ("report readiness and method appendix", _self_test_report_readiness_and_method_appendix),
        ("visual interpretation checklist", _self_test_visual_interpretation_checklist),
        ("category probability curve data", _self_test_category_probability_curve_data),
        ("export bundle contents", _self_test_export_bundle_contents),
        ("anchor audit", _self_test_anchor_audit),
        ("script support boundaries", _self_test_script_support_boundaries),
        ("reproducibility fingerprints", _self_test_reproducibility_fingerprints),
        ("cached static assets and exports", _self_test_cached_static_assets_and_exports),
        ("cross-package validation plan", _self_test_cross_package_validation_plan),
        ("public beta release contract", _self_test_public_beta_release_contract),
        ("APA 7 reference list generator", _self_test_apa_reference_list),
        ("Word publication document builder", _self_test_publication_document_word),
        ("PDF publication document builder", _self_test_publication_document_pdf),
        ("Posterior Viewer loaders / plots", _self_test_posterior_viewer_loaders),
        ("Unified chart guide library", _self_test_chart_guide_library),
        ("Advanced-model Stan generators", _self_test_advanced_model_generators),
    ]
    failures = []
    for name, test_func in tests:
        try:
            test_func()
            print(f"[PASS] {name}")
        except Exception as exc:
            failures.append((name, exc))
            print(f"[FAIL] {name}: {exc}")
    if failures:
        print(f"\n{len(failures)} self-test(s) failed.")
        return 1
    print(f"\nAll {len(tests)} self-tests passed.")
    return 0


# ---------------------------------------------------------------------------
# Unified chart interpretation guide (D3)
# ---------------------------------------------------------------------------
# Every diagnostic plot across the Visuals / Dimensionality / Wright Map
# sections ends up under a familiar ❓ "How to read this" expander rendered
# by render_chart_guide. Keeping the library in one place prevents the
# explanatory text from drifting between tabs.

_CHART_GUIDE_LIBRARY: dict[str, dict[str, str]] = {
    "wright_map": {
        "headline": "Wright Map — persons (left) vs item/facet elements (right) on a common logit scale.",
        "body": (
            "**How to read:** higher = more able persons / harder items. "
            "A healthy map has items spread across the person range (good "
            "targeting); items clustered above the person mean imply a test "
            "too hard, below imply too easy. Wright & Stone (1999) and "
            "Linacre (2024) call this the primary visual check."
        ),
    },
    "pathway_map": {
        "headline": "Pathway Map — measure on x-axis, Infit MnSq on y-axis, with element labels.",
        "body": (
            "**How to read:** points near y = 1.0 fit the Rasch expectation. "
            "Values > 1.4 indicate noisy (distorting) responses for that "
            "element; values < 0.6 indicate over-fit (Wright & Linacre, 1994)."
        ),
    },
    "category_probability": {
        "headline": "Category Probability Curves — probability of each response category vs latent trait.",
        "body": (
            "**How to read:** each curve should peak exclusively at some "
            "trait range, and all categories should be the most probable "
            "choice over some interval. Overlapping / dominated curves "
            "suggest an unused or redundant category (Linacre, 2004; "
            "Andrich, 1978)."
        ),
    },
    "threshold_map": {
        "headline": "Threshold Map — ordered step thresholds across elements.",
        "body": (
            "**How to read:** adjacent thresholds should increase "
            "monotonically. Disordered thresholds (a later step with a "
            "lower threshold) flag category misuse (Linacre, 2002)."
        ),
    },
    "icc": {
        "headline": "ICC — Item Characteristic Curve overlaying observed vs expected scores.",
        "body": (
            "**How to read:** the empirical (dots) should track the "
            "model-implied S-curve. Systematic departures indicate model "
            "misfit or multidimensionality."
        ),
    },
    "scree": {
        "headline": "Scree Plot — eigenvalues of the residual correlation matrix.",
        "body": (
            "**How to read:** the first eigenvalue < 2.0 supports "
            "unidimensionality; 2.0–3.0 is a grey zone; > 3.0 flags a "
            "strong secondary dimension. Eigenvalues of the residuals "
            "should then hover near 1.0 (Smith, 2002; Linacre, 2024)."
        ),
    },
    "facet_distribution": {
        "headline": "Facet Distribution — boxplots / strip plots of element measures by facet.",
        "body": (
            "**How to read:** compare the spread of each facet's measures. "
            "A facet with very tight measures contributes less to person "
            "ordering; very wide spread may warrant splitting."
        ),
    },
    "reliability": {
        "headline": "Reliability / Separation — separation index and Rasch reliability per facet.",
        "body": (
            "**How to read:** person separation ≥ 2 (reliability ≥ 0.80) "
            "is usually the floor for scoring decisions; ≥ 3 for higher "
            "stakes (Linacre, 2024). Non-person facets report the same "
            "quantities but interpret them as precision of the facet's "
            "element measures."
        ),
    },
    "rater_agreement": {
        "headline": "Rater Agreement — exact / adjacent percent agreement and κ.",
        "body": (
            "**How to read:** MFRM does not require high agreement; the "
            "model itself absorbs rater severity. Still, very low agreement "
            "(< 40% exact) combined with poor fit suggests rater-specific "
            "confusion (Myford & Wolfe, 2003)."
        ),
    },
    "posterior_trace": {
        "headline": "Trace Plot — chain-by-chain draws across iterations.",
        "body": (
            "**How to read:** chains should overlap and wander without "
            "trends (the hairy caterpillar). Separated or drifting chains "
            "imply non-mixing; Rhat ≥ 1.01 confirms it (Gelman & Rubin, 1992)."
        ),
    },
    "posterior_ridge": {
        "headline": "Ridge Plot — posterior densities stacked across parameters.",
        "body": (
            "**How to read:** compare shape and location at a glance. "
            "Bimodal / skewed densities often point to identifiability or "
            "prior-sensitivity issues (Kruschke, 2018)."
        ),
    },
}


